import { beforeEach, describe, it } from 'vitest';
import { beforeAll } from 'vitest';
import { mock } from 'jest-mock-extended';
import { supabase } from '@/lib/supabase';
import { appendChangeLog } from '@/server/repo';
import { snakeCase } from '@/utils/case';

const mockSupabase = mock();
mockSupabase.auth = mock();
mockSupabase.auth.getSession = jest.fn().mockResolvedValue({ data: { session: null }, error: null });
mockSupabase.from = jest.fn().mockReturnValue(mockSupabase);
mockSupabase.from().insert = jest.fn().mockResolvedValue({ data: [], error: null });

beforeEach(() => {
  jest.resetAllMocks();
  supabase.from = mockSupabase.from;
});

describe('appendChangeLog', () => {
  it('should insert changelog entry without explicit id', async () => {
    const payload = {
      user_id: 'user-123',
      table: 'library',
      action: 'update',
      data: {
        id: 'item-456',
        name: 'New Item'
      }
    };

    await appendChangeLog(payload);

    expect(mockSupabase.from().insert).toHaveBeenCalledWith({
      user_id: 'user-123',
      table: 'library',
      action: 'update',
      data: {
        item_id: 'item-456',
        name: 'New Item'
      }
    });
  });

  it('should propagate insert errors', async () => {
    const payload = {
      user_id: 'user-123',
      table: 'library',
      action: 'update',
      data: {
        id: 'item-456',
        name: 'New Item'
      }
    };

    mockSupabase.from().insert = jest.fn().mockRejectedValue(new Error('Insert failed'));

    await expect(appendChangeLog(payload)).rejects.toThrow('Insert failed');
  });
});

